Author:     Brendan Abolivier <brendan@thunderbird.net>
AuthorDate: Tue Aug 5 17:21:16 2025 -0400
Commit:     Brendan Abolivier <brendan@thunderbird.net>
CommitDate: Tue Aug 5 17:21:16 2025 -0400

    Bug 1910983 - Apply our remote content policy based on the existence of a message DB entry rather than the type of URI. r=tobyp


    EWS URIs don't implement `nsIMsgMailNewsUrl`/`nsIMsgMessageUrl`, and as a result
    remote content is never blocked in EWS messages.

    This patch changes the criteria used to decide whether to enforce our remote
    content policy: rather than checking if the URI implements one of the
    aforementioned interfaces to figure out whether an URI targets a message, we
    check if it can be mapped to an entry in the relevant message DB.

    Differential Revision: https://phabricator.services.mozilla.com/D258726

diff --git a/mailnews/base/src/nsMsgContentPolicy.cpp b/mailnews/base/src/nsMsgContentPolicy.cpp
index 249bae08cd9..e09de2a65ee 100644
--- a/mailnews/base/src/nsMsgContentPolicy.cpp
+++ b/mailnews/base/src/nsMsgContentPolicy.cpp
@@ -625,20 +625,34 @@ void nsMsgContentPolicy::ShouldAcceptContentForPotentialMsg(
   nsresult rv;
   nsCOMPtr<nsIMsgMessageUrl> msgUrl(
       do_QueryInterface(aRequestingLocation, &rv));
-  if (NS_FAILED(rv)) {
-    // It isn't a mailnews url - so we accept the load here, and let other
-    // content policies make the decision if we should be loading it or not.
-    *aDecision = nsIContentPolicy::ACCEPT;
-    return;
-  }

   nsCString resourceURI;
-  rv = msgUrl->GetUri(resourceURI);
+  if (NS_SUCCEEDED(rv)) {
+    rv = msgUrl->GetUri(resourceURI);
+    NS_ENSURE_SUCCESS_VOID(rv);
+  } else {
+    rv = aRequestingLocation->GetSpec(resourceURI);
+    NS_ENSURE_SUCCESS_VOID(rv);
+  }
+
+  nsCString scheme;
+  rv = aRequestingLocation->GetScheme(scheme);
   NS_ENSURE_SUCCESS_VOID(rv);

   nsCOMPtr<nsIMsgDBHdr> msgHdr;
   rv = GetMsgDBHdrFromURI(resourceURI, getter_AddRefs(msgHdr));

+  // Check if we have an entry in the relevant message DB for the URI. If the
+  // URI's scheme is `mailbox`, we carry on regardless, because such URIs can
+  // refer to messages read from a file rather than from a specific folder (in
+  // which case they won't have a message DB entry). Otherwise, if the URI isn't
+  // for a message we know of, we accept the load here, and let other content
+  // policies make the decision if we should be loading it or not.
+  if (!scheme.EqualsLiteral("mailbox") && (NS_FAILED(rv) || !msgHdr)) {
+    *aDecision = nsIContentPolicy::ACCEPT;
+    return;
+  }
+
   // Get a decision on whether or not to allow remote content for this message
   // header.
   *aDecision = ShouldAcceptRemoteContentForMsgHdr(msgHdr, aRequestingLocation,
